fn is_non_prime(n: u64) -> bool {
    // n is assumed to be >= 2
    if n <= 3 {
        return false; // 2 and 3 are prime
    }
    if n % 2 == 0 {
        return true; // even and > 2 => composite
    }

    // Check odd divisors up to sqrt(n)
    let mut k: u64 = 3;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 2;
    }
    false
}